    let (snapshot, result) = store.get(4, &empty, 22, 0).unwrap();
    assert!(snapshot.result_is_error);
    assert_eq!(snapshot.result_length, 0);
    assert!(result.bytes.is_empty());

    let active = start(&store, 4, 30, 72);
    let too_large = vec![0; RESULT_LIMIT + 1];
    assert_eq!(store.finish(4, &active, 31, TaskStatus::Failed, b"oversized", &too_large, false),
        Err(TaskStoreError::ResultTooLarge { length: RESULT_LIMIT + 1, maximum: RESULT_LIMIT }));
    assert_eq!(store.finish(4, &active, 32, TaskStatus::Working, b"invalid", &[], false), Err(TaskStoreError::InvalidStatus));
    assert_eq!(store.finish(4, &active, 32, TaskStatus::Failed, &vec![b'm'; MESSAGE_LIMIT + 1], &[], false), Err(TaskStoreError::MessageTooLong));
    store.finish(4, &active, 33, TaskStatus::Completed, b"at limit", &vec![0xA5; RESULT_LIMIT], false).unwrap();
    let (_, copy) = store.get(4, &active, 34, RESULT_LIMIT).unwrap();
    assert_eq!(copy.bytes.len(), RESULT_LIMIT);
    assert!(copy.bytes.iter().all(|byte| *byte == 0xA5));
}

